function vender(db, produtoId, qtd) {
  db.exec('BEGIN');
  try {
    const stmt = db.prepare('UPDATE produtos SET estoque = estoque - ? WHERE id = ? AND estoque >= ?');
    const result = stmt.run(qtd, produtoId, qtd);
    if (result.changes === 0) {
      db.exec('ROLLBACK');
      throw new Error('Estoque insuficiente');
    }
    db.prepare('INSERT INTO vendas (produto_id, qtd) VALUES (?, ?)').run(produtoId, qtd);
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}
