function vender(db, produtoId, qtd) {
  const produto = db.prepare('SELECT estoque FROM produtos WHERE id = ?').get(produtoId);

  if (!produto) {
    throw new Error('Produto não encontrado');
  }

  if (produto.estoque < qtd) {
    throw new Error('Estoque insuficiente');
  }

  const transaction = db.transaction((id, quantidade) => {
    db.prepare('INSERT INTO vendas (produto_id, qtd) VALUES (?, ?)').run(id, quantidade);
    db.prepare('UPDATE produtos SET estoque = estoque - ? WHERE id = ?').run(quantidade, id);
  });

  transaction(produtoId, qtd);
}
```

