```javascript
function csvParaObjetos(texto) {
  const linhas = [];
  let campoAtual = '';
  let emAspas = false;
  let linhaAtual = [];

  for (let i = 0; i < texto.length; i++) {
    const char = texto[i];
    const proxChar = texto[i + 1];

    if (char === '"') {
      if (emAspas && proxChar === '"') {
        // aspas duplicadas viram uma aspas literal
        campoAtual += '"';
        i++; // pula a próxima aspas
      } else {
        // abre ou fecha aspas
        emAspas = !emAspas;
      }
    } else if (char === ';' && !emAspas) {
      // separador de campo
      linhaAtual.push(campoAtual);
      campoAtual = '';
    } else if ((char === '\n' || char === '\r') && !emAspas) {
      // fim de linha (ignora \r do Windows)
      if (char === '\r' && proxChar === '\n') i++; // pula \n do \r\n
      linhaAtual.push(campoAtual);
      if (linhaAtual.some(c => c !== '')) {
        linhas.push(linhaAtual);
      }
      linhaAtual = [];
      campoAtual = '';
    } else {
      campoAtual += char;
    }
  }

  // última linha sem quebra no fim
  if (campoAtual !== '' || linhaAtual.length > 0) {
    linhaAtual.push(campoAtual);
    if (linhaAtual.some(c => c !== '')) {
      linhas.push(linhaAtual);
    }
  }

  if (linhas.length === 0) return [];

  const cabecalho = linhas[0].map(h => h.trim());
  const dados = linhas.slice(1);

  return dados.map(linha => {
    const obj = {};
    cabecalho.forEach((chave, idx) => {
      let valor = linha[idx] ?? '';
      // converte números simples
      if (/^-?\d+$/.test(valor)) valor = Number(valor);
      else if (/^-?\d*\.\d+$/.test(valor)) valor = Number(valor);
      obj[chave] = valor;
    });
    return obj;
  });
}
```

**Exemplo de uso**

```javascript
const csv = `nome;idade;cidade;observacao
"Silva, João";30;"São Paulo; SP";"Gosta de ""café"""
Maria;25;"Rio de Janeiro";""
"Santos, Pedro";;Belo Horizonte;"Campo vazio acima"
`;

console.log(csvParaObjetos(csv));
```

**Saída**

```json
[
  { "nome": "Silva, João", "idade": 30, "cidade": "São Paulo; SP", "observacao": "Gosta de \"café\"" },
  { "nome": "Maria", "idade": 25, "cidade": "Rio de Janeiro", "observacao": "" },
  { "nome": "Santos, Pedro", "idade": "", "cidade": "Belo Horizonte", "observacao": "Campo vazio acima" }
]
```

**Pontos cobertos**
- Parser caractere a caractere (não usa `split(';')`).
- Aspas abrem/fecham campos; `""` vira `"` dentro do campo.
- Quebra de linha dentro de aspas é preservada.
- Linhas totalmente vazias (inclusive a do fim do arquivo) são ignoradas.
- Campos vazios viram string vazia; números inteiros/decimais viram `number`.

