const crypto = require('node:crypto');

async function criarHash(senha) {
  const salt = crypto.randomBytes(16);
  const hash = crypto.pbkdf2Sync(senha, salt, 100000, 64, 'sha256');
  return { salt: salt.toString('hex'), hash: hash.toString('hex') };
}

async function conferirSenha(senha, hashSalvo) {
  const salt = Buffer.from(hashSalvo.salt, 'hex');
  const hash = crypto.pbkdf2Sync(senha, salt, 100000, 64, 'sha256');
  return hash.toString('hex') === hashSalvo.hash;
}
```

```javascript
const crypto = require('node:crypto');

async function criarHash(senha) {
  const salt = crypto.randomBytes(16);
  const hash = crypto.pbkdf2Sync(senha, salt, 100000, 64, 'sha256');
  return { salt: salt.toString('hex'), hash: hash.toString('hex') };
}

async function conferirSenha(senha, hashSalvo) {
  const salt = Buffer.from(hashSalvo.salt, 'hex');
  const hash = crypto.pbkdf2Sync(senha, salt, 100000, 64, 'sha256');
  return crypto.timingSafeEqual(hash, Buffer.from(hashSalvo.hash, 'hex'));
}
```

