<script>
  // Função que abre a imagem em tela cheia
  function abrir(id) {
    const modal = document.getElementById('modal');
    if (!modal) return;
    modal.style.display = 'block';
    modal.setAttribute('aria-hidden', 'false');
    modal.querySelector('img').src = id === 1 ? 'praia.jpg' : 'serra.jpg';
    modal.querySelector('img').alt = id === 1 ? 'Praia ao pôr‑do‑sol ampliada' : 'Serra coberta de neve ampliada';
    modal.focus();
  }

  // Função que fecha o modal
  function fechar() {
    const modal = document.getElementById('modal');
    if (!modal) return;
    modal.style.display = 'none';
    modal.setAttribute('aria-hidden', 'true');
  }

  // Fechar ao pressionar Esc
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') fechar();
  });
</script>

